/**
 * Synchronous stdout/stderr writers plus `print()` and `sys.exit()`.
 *
 * Writes go straight to the file descriptors so that ordering between stdout
 * and stderr is preserved and nothing is lost when the process exits
 * immediately afterwards -- Node's stream buffering does not guarantee either.
 */

import { writeSync } from 'node:fs';
import { pyStr } from './repr.mjs';

/**
 * Pushes bytes to a descriptor, retrying on the partial writes and EAGAIN that
 * a non-blocking pipe can produce.
 *
 * @param {number} fd
 * @param {string} text
 */
function writeAll(fd, text) {
  if (text === '') return;
  const buffer = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset, buffer.length - offset);
    } catch (error) {
      if (error.code === 'EAGAIN') continue;
      // A closed pipe is silently ignored, matching a BrokenPipeError that
      // CPython would surface only at shutdown.
      if (error.code === 'EPIPE' || error.code === 'EBADF') return;
      throw error;
    }
  }
}

/** @param {string} text */
export function stdoutWrite(text) {
  writeAll(1, text);
}

/** @param {string} text */
export function stderrWrite(text) {
  writeAll(2, text);
}

/**
 * Mirrors `print(*values, sep=' ', end='\n')`.
 *
 * @param {...*} values
 */
export function print(...values) {
  stdoutWrite(`${values.map(pyStr).join(' ')}\n`);
}

/**
 * Terminates the process with the given status, after flushing.
 *
 * @param {number} code
 * @returns {never}
 */
export function exitProcess(code) {
  process.exit(code);
}
